// Patch existing SVG nodes instead of destroying loaded images and canvases.
const key=n=>n.nodeType===1?(n.getAttribute('id')||n.getAttribute('data-node-key')):null;
export function patchSvg(root,markup){const next=document.createElementNS('http://www.w3.org/2000/svg','svg');next.innerHTML=markup;sync(root,next);}
function sync(old,next){const previous=[...old.childNodes],used=new Set();let cursor=old.firstChild;for(const fresh of [...next.childNodes]){const k=key(fresh);let node=k?previous.find(n=>!used.has(n)&&key(n)===k):previous.find(n=>!used.has(n)&&!key(n)&&n.nodeType===fresh.nodeType&&n.nodeName===fresh.nodeName);if(!node){node=fresh.cloneNode(true);old.append(node);}else{if(node.nodeType===1){for(const a of [...node.attributes])if(!fresh.hasAttribute(a.name))node.removeAttribute(a.name);for(const a of [...fresh.attributes])if(node.getAttribute(a.name)!==a.value)node.setAttribute(a.name,a.value);if(node.nodeName.toLowerCase()!=='canvas')sync(node,fresh);}else if(node.nodeValue!==fresh.nodeValue)node.nodeValue=fresh.nodeValue;}used.add(node);if(node!==cursor)old.insertBefore(node,cursor);cursor=node.nextSibling;}for(const node of previous)if(!used.has(node))node.remove();}
